def test_score_stops_before_the_read_on_a_routing_file_with_a_seed_missing(env, monkeypatch):
    s = load("src/08_routing.py")
    for p in s.read_needs():
        p.parent.mkdir(parents=True, exist_ok=True); p.touch()
    R = routing()
